"use strict";
let lastFocusedBeforeModal = null;
function modalKeydownHandler(e){
  if(e.key === "Escape") closeModal();
}
function closeModal(){
  currentModal = null;
  document.getElementById("modalRoot").innerHTML = "";
  document.removeEventListener("keydown", modalKeydownHandler);
  if(lastFocusedBeforeModal && document.body.contains(lastFocusedBeforeModal)){
    lastFocusedBeforeModal.focus();
  }
  lastFocusedBeforeModal = null;
}
function openModal(which){
  currentModal = which;
  const root = document.getElementById("modalRoot");
  if(which === "profile") root.innerHTML = profileModalHTML();
  if(which === "history") root.innerHTML = historyModalHTML();
  if(which === "settings") root.innerHTML = settingsModalHTML();
  if(which === "privacy") root.innerHTML = privacyModalHTML();
  if(which === "vote") root.innerHTML = voteModalHTML();
  if(which === "about") root.innerHTML = aboutModalHTML();
  if(which === "proposal") root.innerHTML = proposalModalHTML();
  /* Wire up dialog semantics + keyboard behaviour once, here, instead of in
     every modal template — works uniformly regardless of each modal's markup. */
  const box = root.querySelector(".modalbox");
  if(box){
    box.setAttribute("role", "dialog");
    box.setAttribute("aria-modal", "true");
    const heading = box.querySelector("h2");
    if(heading){
      if(!heading.id) heading.id = "modalTitle";
      box.setAttribute("aria-labelledby", heading.id);
    }
    box.setAttribute("tabindex", "-1");
    lastFocusedBeforeModal = document.activeElement;
    box.focus();
    document.addEventListener("keydown", modalKeydownHandler);
  }
}

/* ---------- Profile ---------- */
function profileModalHTML(){
  const u = auth && auth.currentUser;
  if(!u) return "";
  const name = u.displayName || "";
  const email = u.email || "";
  const isGoogle = u.providerData.some(p=>p.providerId==="google.com");
  return `<div class="modaloverlay" onclick="if(event.target===this)closeModal()">
    <div class="modalbox">
      <button class="close" onclick="closeModal()" aria-label="Close">&times;</button>
      <h2>${t("profileTitle")}</h2>
      <p class="sub">${email}</p>

      <section>
        <h3>${t("profileDisplayName")}</h3>
        <div style="display:flex;gap:8px">
          <input class="field2" id="pfName" style="flex:1" value="${name}" placeholder="${t('profileNamePlaceholder')}">
          <button class="btn" onclick="saveDisplayName()">${t("profileSave")}</button>
        </div>
        <p id="pfNameMsg" class="sub2" style="margin-top:6px"></p>
      </section>

      ${isGoogle ? "" : `
      <section>
        <h3>${t("profileChangePass")}</h3>
        <div class="field" style="margin-bottom:8px"><input class="field2" style="width:100%" type="password" id="pfCurPass" placeholder="${t('profileCurPass')}"></div>
        <div class="field" style="margin-bottom:8px"><input class="field2" style="width:100%" type="password" id="pfNewPass" placeholder="${t('profileNewPass')}"></div>
        <button class="btn" onclick="changePassword()">${t("profileUpdatePass")}</button>
        <p id="pfPassMsg" class="sub2" style="margin-top:6px"></p>
      </section>`}

      <section>
        <h3>${t("profileDeleteAccount")}</h3>
        <div class="dangerzone">
          <p>${t("profileDeleteWarn")}</p>
          <button class="btn bad" onclick="deleteAccount()">${t("profileDeleteBtn")}</button>
        </div>
        <p id="pfDelMsg" class="sub2" style="margin-top:6px"></p>
      </section>
    </div>
  </div>`;
}
function saveDisplayName(){
  const u = auth.currentUser; const val = document.getElementById("pfName").value.trim();
  const msg = document.getElementById("pfNameMsg");
  u.updateProfile({displayName: val})
    .then(()=>{ msg.textContent=t("msgSaved"); msg.style.color="#2C5220";
      document.getElementById("gmBadge").innerHTML = `Signed in as <b>${val||u.email}</b> <button class="authlink" onclick="signOutGM()">Sign out</button>`; })
    .catch(e=>{ msg.textContent=friendlyAuthError(e); msg.style.color="#7A2620"; });
}
function changePassword(){
  const u = auth.currentUser;
  const cur = document.getElementById("pfCurPass").value;
  const next = document.getElementById("pfNewPass").value;
  const msg = document.getElementById("pfPassMsg");
  if(!cur || !next){ msg.textContent=t("msgFillBoth"); msg.style.color="#7A2620"; return; }
  const cred = firebase.auth.EmailAuthProvider.credential(u.email, cur);
  u.reauthenticateWithCredential(cred)
    .then(()=>u.updatePassword(next))
    .then(()=>{ msg.textContent=t("msgPassUpdated"); msg.style.color="#2C5220";
      document.getElementById("pfCurPass").value=""; document.getElementById("pfNewPass").value=""; })
    .catch(e=>{ msg.textContent=friendlyAuthError(e); msg.style.color="#7A2620"; });
}
function deleteAccount(){
  const u = auth.currentUser;
  const msg = document.getElementById("pfDelMsg");
  if(!confirm(t("confirmDeleteAccount"))) return;
  const isGoogle = u.providerData.some(p=>p.providerId==="google.com");
  const proceed = () => u.delete()
    .then(()=>{ closeModal(); })
    .catch(e=>{ msg.textContent=friendlyAuthError(e); msg.style.color="#7A2620"; });
  if(isGoogle){
    const provider = new firebase.auth.GoogleAuthProvider();
    u.reauthenticateWithPopup(provider).then(proceed).catch(e=>{ msg.textContent=friendlyAuthError(e); msg.style.color="#7A2620"; });
  } else {
    const pass = prompt(t("promptReenterPass"));
    if(!pass){ return; }
    const cred = firebase.auth.EmailAuthProvider.credential(u.email, pass);
    u.reauthenticateWithCredential(cred).then(proceed).catch(e=>{ msg.textContent=friendlyAuthError(e); msg.style.color="#7A2620"; });
  }
}

/* ---------- History ---------- */
function historyModalHTML(){
  const h = getHistory();
  const statusLabel = (e) => {
    if(e.status === "finished") return `<b>${e.winner}</b> ${t("historyWon")}`;
    if(e.status === "abandoned") return `<span style="color:#7A2620">${t("historyAbandoned")}</span>`;
    return `<span style="color:#8F6A2C">${t("historyInProgress")}</span>`;
  };
  return `<div class="modaloverlay" onclick="if(event.target===this)closeModal()">
    <div class="modalbox">
      <button class="close" onclick="closeModal()" aria-label="Close">&times;</button>
      <h2>${t("historyTitle")}</h2>
      <p class="sub">${t("historySub")}</p>
      ${h.length===0 ? `<p class="histempty">${t("historyEmpty")}</p>` :
        h.map(e=>`<div class="histrow">
          <span>${new Date(e.date).toLocaleDateString()} · ${e.teamCount} ${t("teamsWord")}</span>
          <span>${statusLabel(e)}</span>
        </div>`).join("")}
      ${h.length>0 ? `<div style="margin-top:14px"><button class="btn bad" onclick="clearHistory()">${t("historyClear")}</button></div>` : ""}
    </div>
  </div>`;
}

