/* ---------- Vote (EU-Parliament-style roll call) ---------- */
window.__voteState = window.__voteState || null;
function voteModalHTML(){
  if(!teams || teams.length === 0){
    return `<div class="modaloverlay" onclick="if(event.target===this)closeModal()">
      <div class="modalbox">
        <button class="close" onclick="closeModal()" aria-label="Close">&times;</button>
        <h2>${t("holdVote")}</h2>
        <p class="sub">${t("voteNeedGame")}</p>
      </div>
    </div>`;
  }
  if(!window.__voteState){
    window.__voteState = { topic: "", votes: {} };
    teams.forEach(tm => window.__voteState.votes[tm.name] = null);
  }
  const vs = window.__voteState;
  const forCount = teams.filter(tm=>vs.votes[tm.name]==="for").length;
  const againstCount = teams.filter(tm=>vs.votes[tm.name]==="against").length;
  const abstainCount = teams.filter(tm=>vs.votes[tm.name]==="abstain").length;
  const allCast = teams.every(tm=>vs.votes[tm.name]!==null);
  return `<div class="modaloverlay" onclick="if(event.target===this)closeModal()">
    <div class="modalbox" style="max-width:560px">
      <button class="close" onclick="closeModal()" aria-label="Close">&times;</button>
      <h2>${t("holdVote")}</h2>
      <p class="sub">${t("voteSub")}</p>
      <div class="field" style="margin-bottom:14px">
        <label for="voteTopic">${t("voteMotion")}</label>
        <input class="field2" id="voteTopic" style="width:100%" placeholder="${t('voteMotionPlaceholder')}"
          value="${vs.topic.replace(/"/g,'&quot;')}" oninput="window.__voteState.topic=this.value">
      </div>
      ${teams.map(tm=>`
        <div class="settingrow">
          <div><span class="dot" style="background:${tm.color};margin-right:6px"></span>${tm.name}</div>
          <div class="btnrow" style="margin-top:0">
            <button class="btn ${vs.votes[tm.name]==='for'?'good':''}" onclick="castVote('${tm.name.replace(/'/g,"\\'")}','for')">${t("voteFor")}</button>
            <button class="btn ${vs.votes[tm.name]==='against'?'bad':''}" onclick="castVote('${tm.name.replace(/'/g,"\\'")}','against')">${t("voteAgainst")}</button>
            <button class="btn ${vs.votes[tm.name]==='abstain'?'primary':''}" onclick="castVote('${tm.name.replace(/'/g,"\\'")}','abstain')">${t("voteAbstain")}</button>
          </div>
        </div>`).join("")}
      <p class="sub" style="margin-top:12px">${t("voteTallySoFar")} <b>${forCount}</b> ${t("voteAgainstLbl")} <b>${againstCount}</b> ${t("voteAbstainLbl")} <b>${abstainCount}</b></p>
      <div class="btnrow" style="margin-top:10px">
        <button class="btn primary" ${allCast?"":"disabled"} onclick="finishVote()">${t("declareResult")}</button>
        <button class="btn" onclick="resetVote()">${t("resetVote")}</button>
      </div>
    </div>
  </div>`;
}
function castVote(teamName, choice){
  window.__voteState.votes[teamName] = choice;
  document.getElementById("modalRoot").innerHTML = voteModalHTML();
}
function resetVote(){
  window.__voteState = null;
  document.getElementById("modalRoot").innerHTML = voteModalHTML();
}
function finishVote(){
  const vs = window.__voteState;
  const forCount = teams.filter(tm=>vs.votes[tm.name]==="for").length;
  const againstCount = teams.filter(tm=>vs.votes[tm.name]==="against").length;
  const abstainCount = teams.filter(tm=>vs.votes[tm.name]==="abstain").length;
  const result = forCount > againstCount ? t("voteAdopted") : t("voteRejected");
  const topic = vs.topic.trim() || t("untitledMotion");
  log(`🗳️ Vote — <b>${topic}</b>: For ${forCount}, Against ${againstCount}, Abstain ${abstainCount} — <b>${result}</b>`);
  track("vote_held", { for_count: forCount, against_count: againstCount, abstain_count: abstainCount });
  window.__voteState = null;
  closeModal();
}

