/* ---------- Proposal capstone: Analyse → Position → Negotiate → Vote ---------- */
window.__proposal = window.__proposal || null;
function newProposalState(){
  return { stage:0, topic:"", positions:{}, votes:{}, timerLeft:0, timerInt:null, timerPaused:false };
}
function proposalModalHTML(){
  if(!teams || teams.length === 0){
    return `<div class="modaloverlay" onclick="if(event.target===this)closeModal()">
      <div class="modalbox">
        <button class="close" onclick="closeModal()" aria-label="Close">&times;</button>
        <h2>${t("proposalTitle")}</h2>
        <p class="sub">${t("proposalNeedGame")}</p>
      </div>
    </div>`;
  }
  if(!window.__proposal) window.__proposal = newProposalState();
  const p = window.__proposal;
  let body = "";
  if(p.stage === 0) body = proposalStage0();
  else if(p.stage === 1) body = proposalStage1();
  else if(p.stage === 2) body = proposalStage2();
  else if(p.stage === 3) body = proposalStage3();
  else body = proposalStage4();
  return `<div class="modaloverlay" onclick="if(event.target===this)closeModal()">
    <div class="modalbox" style="max-width:600px">
      <button class="close" onclick="closeModal()" aria-label="Close">&times;</button>
      <h2>${t("proposalTitle")}</h2>
      ${body}
    </div>
  </div>`;
}
function proposalRefresh(){ document.getElementById("modalRoot").innerHTML = proposalModalHTML(); }

function proposalStage0(){
  const p = window.__proposal;
  return `
    <h3 style="margin-top:10px">${t("proposalStage0Title")}</h3>
    <p class="sub">${t("proposalStage0Sub")}</p>
    <input class="field2" style="width:100%" id="propTopic" placeholder="${t('proposalTopicPlaceholder')}"
      value="${p.topic.replace(/"/g,'&quot;')}" oninput="window.__proposal.topic=this.value">
    <div class="btnrow" style="margin-top:16px">
      <button class="btn primary" onclick="proposalNext()">${t("proposalNext")}</button>
    </div>`;
}
function proposalStage1(){
  const p = window.__proposal;
  return `
    <h3 style="margin-top:10px">${t("proposalStage1Title")}</h3>
    <p class="sub">${t("proposalStage1Sub")}</p>
    <p class="sub2" style="margin-bottom:10px"><b>${p.topic || "—"}</b></p>
    ${teams.map(tm=>`
      <div class="settingrow">
        <div><span class="dot" style="background:${tm.color};margin-right:6px"></span>${tm.name}</div>
        <input class="field2" style="flex:1;max-width:260px" placeholder="${t('proposalPositionPlaceholder')}"
          value="${(p.positions[tm.name]||'').replace(/"/g,'&quot;')}"
          oninput="window.__proposal.positions['${tm.name.replace(/'/g,"\\'")}']=this.value">
      </div>`).join("")}
    <div class="btnrow" style="margin-top:16px">
      <button class="btn" onclick="proposalBack()">${t("proposalBack")}</button>
      <button class="btn primary" onclick="proposalNext()">${t("proposalNext")}</button>
    </div>`;
}
function proposalStage2(){
  const p = window.__proposal;
  return `
    <h3 style="margin-top:10px">${t("proposalStage2Title")}</h3>
    <p class="sub">${t("proposalStage2Sub")}</p>
    <div class="btnrow">
      <button class="btn" id="propTimerStartBtn" onclick="proposalStartTimer(180)">⏱ 3:00</button>
      <button class="btn hidden" id="propTimerPauseBtn" onclick="proposalPauseTimer()">⏸ ${t("pause")}</button>
      <button class="btn hidden" id="propTimerStopBtn" onclick="proposalStopTimer()">⏹ ${t("stop")}</button>
      <span class="timer-digit hidden" id="propTimerDisplay"></span>
    </div>
    <div class="btnrow" style="margin-top:16px">
      <button class="btn" onclick="proposalBack()">${t("proposalBack")}</button>
      <button class="btn primary" onclick="proposalNext()">${t("proposalNext")}</button>
    </div>`;
}
function proposalStage3(){
  const p = window.__proposal;
  teams.forEach(tm => { if(!(tm.name in p.votes)) p.votes[tm.name] = null; });
  const forCount = teams.filter(tm=>p.votes[tm.name]==="for").length;
  const againstCount = teams.filter(tm=>p.votes[tm.name]==="against").length;
  const abstainCount = teams.filter(tm=>p.votes[tm.name]==="abstain").length;
  const allCast = teams.every(tm=>p.votes[tm.name]!==null);
  return `
    <h3 style="margin-top:10px">${t("proposalStage3Title")}</h3>
    <p class="sub">${t("proposalStage3Sub")}</p>
    <p class="sub2" style="margin-bottom:10px"><b>${p.topic || "—"}</b></p>
    ${teams.map(tm=>`
      <div class="settingrow">
        <div><span class="dot" style="background:${tm.color};margin-right:6px"></span>${tm.name}</div>
        <div class="btnrow" style="margin-top:0">
          <button class="btn ${p.votes[tm.name]==='for'?'good':''}" onclick="proposalVote('${tm.name.replace(/'/g,"\\'")}','for')">${t("voteFor")}</button>
          <button class="btn ${p.votes[tm.name]==='against'?'bad':''}" onclick="proposalVote('${tm.name.replace(/'/g,"\\'")}','against')">${t("voteAgainst")}</button>
          <button class="btn ${p.votes[tm.name]==='abstain'?'primary':''}" onclick="proposalVote('${tm.name.replace(/'/g,"\\'")}','abstain')">${t("voteAbstain")}</button>
        </div>
      </div>`).join("")}
    <p class="sub" style="margin-top:12px">${t("voteTallySoFar")} <b>${forCount}</b> ${t("voteAgainstLbl")} <b>${againstCount}</b> ${t("voteAbstainLbl")} <b>${abstainCount}</b></p>
    <div class="btnrow" style="margin-top:10px">
      <button class="btn" onclick="proposalBack()">${t("proposalBack")}</button>
      <button class="btn primary" ${allCast?"":"disabled"} onclick="proposalNext()">${t("proposalNext")}</button>
    </div>`;
}
function proposalStage4(){
  const p = window.__proposal;
  const forCount = teams.filter(tm=>p.votes[tm.name]==="for").length;
  const againstCount = teams.filter(tm=>p.votes[tm.name]==="against").length;
  const abstainCount = teams.filter(tm=>p.votes[tm.name]==="abstain").length;
  const result = forCount > againstCount ? t("voteAdopted") : t("voteRejected");
  return `
    <h3 style="margin-top:10px">${t("proposalResultTitle")}</h3>
    <p class="sub2"><b>${p.topic || "—"}</b></p>
    <div class="answerbox" style="margin-top:10px">
      <div class="a">${result}</div>
      <div class="dyk">${t("voteFor")}: ${forCount} · ${t("voteAgainst")}: ${againstCount} · ${t("voteAbstain")}: ${abstainCount}</div>
    </div>
    <p class="sub2" style="margin-top:14px">${t("proposalPositionsRecap")}</p>
    ${teams.map(tm=>`<div class="histrow"><span>${tm.name}</span><span>${p.positions[tm.name] || t("proposalNoPosition")}</span></div>`).join("")}
    <div class="btnrow" style="margin-top:16px">
      <button class="btn primary" onclick="proposalFinish()">${t("proposalFinish")}</button>
      <button class="btn" onclick="proposalReset()">${t("proposalStartOver")}</button>
    </div>`;
}
function proposalNext(){ window.__proposal.stage = Math.min(4, window.__proposal.stage + 1); proposalRefresh(); }
function proposalBack(){ proposalStopTimer(); window.__proposal.stage = Math.max(0, window.__proposal.stage - 1); proposalRefresh(); }
function proposalVote(teamName, choice){ window.__proposal.votes[teamName] = choice; proposalRefresh(); }
function proposalReset(){ window.__proposal = newProposalState(); proposalRefresh(); }
function proposalFinish(){
  const p = window.__proposal;
  const forCount = teams.filter(tm=>p.votes[tm.name]==="for").length;
  const againstCount = teams.filter(tm=>p.votes[tm.name]==="against").length;
  const abstainCount = teams.filter(tm=>p.votes[tm.name]==="abstain").length;
  const result = forCount > againstCount ? t("voteAdopted") : t("voteRejected");
  const topic = p.topic.trim() || t("untitledMotion");
  log(`📝 Proposal — <b>${topic}</b>: For ${forCount}, Against ${againstCount}, Abstain ${abstainCount} — <b>${result}</b>`);
  track("proposal_completed", { for_count: forCount, against_count: againstCount, abstain_count: abstainCount });
  window.__proposal = null;
  closeModal();
}
function proposalStartTimer(secs){
  proposalStopTimer();
  const p = window.__proposal;
  const display = document.getElementById("propTimerDisplay");
  if(!display) return;
  display.classList.remove("hidden","low");
  document.getElementById("propTimerStartBtn").classList.add("hidden");
  document.getElementById("propTimerPauseBtn").classList.remove("hidden");
  document.getElementById("propTimerStopBtn").classList.remove("hidden");
  p.timerLeft = secs; p.timerPaused = false;
  display.textContent = Math.floor(secs/60) + ":" + String(secs%60).padStart(2,"0");
  p.timerInt = setInterval(() => {
    if(p.timerPaused) return;
    p.timerLeft--;
    const d = document.getElementById("propTimerDisplay");
    if(d) d.textContent = Math.floor(p.timerLeft/60) + ":" + String(Math.max(0,p.timerLeft)%60).padStart(2,"0");
    if(p.timerLeft <= 30 && d) d.classList.add("low");
    if(p.timerLeft <= 0){ clearInterval(p.timerInt); p.timerInt = null; Sound.wrong(); }
  }, 1000);
}
function proposalPauseTimer(){
  const p = window.__proposal; if(!p) return;
  p.timerPaused = !p.timerPaused;
  const btn = document.getElementById("propTimerPauseBtn");
  if(btn) btn.textContent = (p.timerPaused ? "▶ " + t("resume") : "⏸ " + t("pause"));
}
function proposalStopTimer(){
  const p = window.__proposal; if(!p) return;
  if(p.timerInt){ clearInterval(p.timerInt); p.timerInt = null; }
  const display = document.getElementById("propTimerDisplay");
  if(display){ display.classList.add("hidden"); display.classList.remove("low"); }
  const startBtn = document.getElementById("propTimerStartBtn"); if(startBtn) startBtn.classList.remove("hidden");
  const pauseBtn = document.getElementById("propTimerPauseBtn"); if(pauseBtn) pauseBtn.classList.add("hidden");
  const stopBtn = document.getElementById("propTimerStopBtn"); if(stopBtn) stopBtn.classList.add("hidden");
}

/* Sound Synthesizer via Web Audio API */
const Sound = {
  ctx: null,
  init() { if (!this.ctx) this.ctx = new (window.AudioContext || window.webkitAudioContext)(); },
  play(freq, type, duration) {
    try {
      if(typeof getSettings === "function" && !getSettings().sound) return;
      this.init();
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.value = freq;
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start();
      gain.gain.setValueAtTime(0.15, this.ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + duration);
      osc.stop(this.ctx.currentTime + duration);
    } catch(e) {}
  },
  roll() { this.play(300, 'square', 0.1); },
  correct() { 
    setTimeout(() => this.play(523.25, 'sine', 0.15), 0);
    setTimeout(() => this.play(659.25, 'sine', 0.25), 120);
  },
  wrong() { 
    setTimeout(() => this.play(220, 'sawtooth', 0.18), 0);
    setTimeout(() => this.play(174.61, 'sawtooth', 0.3), 150);
  },
  win() {
    [440, 554.37, 659.25, 880].forEach((f, i) => {
      setTimeout(() => this.play(f, 'triangle', 0.3), i * 150);
    });
  }
};

